        with tempfile.TemporaryDirectory() as tmpdir, mock.patch(
            "gategpt_testbench_probe.run_gpu_smoke_for_testbench",
            side_effect=AssertionError("default launch smoke should not run"),
        ), mock.patch(
            "gategpt_testbench_probe.run_ordering_aware_full_phase_preflight",
            return_value={
                "status": "ordering_aware_full_phase_preflight_passed",
                "build_status": "passed",
                "module_load_symbol_check_status": "passed",
                "entry_sliced_cubin_chain_paths": [
                    "artifacts/gategpt_tb_core_ptx_entry_slice/vl_eval_patch_feedback_support.cubin",
                    "artifacts/gategpt_tb_core_ptx_entry_slice/vl_feedback_pair_cycle_loop.cubin",
                    "artifacts/gategpt_tb_core_ptx_entry_slice/vl_tb_core_ordering_aware_phase_resident_token_loop_gpu.cubin",
                ],
                "ordering_aware_loop_chunk": 1701,
                "runtime_supported": True,
            },
        ) as preflight, mock.patch(
            "gategpt_testbench_probe.tb_core_structured_output_manifest",
            return_value={"status": "passed"},
        ), mock.patch(
            "gategpt_testbench_probe._gpu_kernel_entrypoint_status",
            return_value={"status": "available"},
        ), mock.patch(
            "gategpt_testbench_probe.define_tb_core_many_independent_scenario_seed_matrix",
            return_value={"status": "seed_matrix_ready"},
        ), mock.patch(
            "gategpt_testbench_probe.generate_tb_core_cpu_oracles_for_seed_matrix",
            return_value={"status": "passed"},
        ), mock.patch(
            "gategpt_testbench_probe.run_tb_core_ordering_aware_token_loop_abi_probe",
            return_value={
                "ordering_aware_loop_chunk": 1701,
                "ordering_aware_full_logical_phase_chunk": True,
                "runtime_supported": True,
                "runtime_correctness_claimed": True,
                "source_probe_comparison": {
                    "state_count": 2,
                    "passed_count": 2,
                    "mismatch_count": 0,
                },
                "ordering_aware_cpu_compare": {},
            },
        ) as probe:
            cwd = Path(tmpdir)
