    def test_full_phase_smoke_stops_early_when_ordering_aware_preflight_fails(
        self,
    ) -> None:
        from gategpt_testbench_probe import run_gate_gpt_gpu_ordering_aware_full_phase_smoke

        with tempfile.TemporaryDirectory() as tmpdir, mock.patch(
            "gategpt_testbench_probe.run_ordering_aware_full_phase_preflight",
            return_value={
                "status": "blocked_ordering_aware_full_phase_module_load_failed",
                "ordering_aware_loop_chunk": 1701,
                "runtime_supported": False,
            },
        ), mock.patch(
            "gategpt_testbench_probe.generate_tb_core_cpu_oracles_for_seed_matrix",
            side_effect=AssertionError("CPU oracle generation should not run"),
        ), mock.patch(
            "gategpt_testbench_probe.run_tb_core_ordering_aware_token_loop_abi_probe",
            side_effect=AssertionError("full-phase probe should not run"),
        ):
            cwd = Path(tmpdir)
            eval_repo = cwd / "gateGPT"
            (eval_repo / "obj_tb_core").mkdir(parents=True)

            result = run_gate_gpt_gpu_ordering_aware_full_phase_smoke(
                cwd,
                eval_repo,
                jobs=1,
                target_state_count=2,
            )

        self.assertEqual(
            result["status"],
            "blocked_ordering_aware_full_phase_module_load_failed",
        )
        self.assertFalse(result["ordering_aware_full_logical_phase_chunk"])
        self.assertFalse(result["speedup_claimed"])
        self.assertFalse(result["usefulness_claimed"])

