    def test_ordering_aware_stage112_store_range_requires_positive_ints(self) -> None:
        from gategpt_testbench_probe import _positive_int, _positive_int_csv

        self.assertEqual(_positive_int("1"), 1)
        self.assertEqual(_positive_int_csv("613, 615"), [613, 615])
        with self.assertRaises(argparse.ArgumentTypeError):
            _positive_int("0")
        with self.assertRaises(argparse.ArgumentTypeError):
            _positive_int("-1")
        with self.assertRaises(argparse.ArgumentTypeError):
            _positive_int_csv("613,,615")
        with self.assertRaises(argparse.ArgumentTypeError):
            _positive_int_csv("613,0")

