    def test_ordering_aware_full_phase_preflight_can_regenerate_stale_sliced_cubins(
        self,
    ) -> None:
        from gategpt_testbench_probe import (
            ORDERING_AWARE_FULL_PHASE_ENTRY_SLICED_CUBINS,
            run_ordering_aware_full_phase_preflight,
        )

        with tempfile.TemporaryDirectory() as tmpdir, mock.patch(
            "gategpt_testbench_probe._gpu_kernel_entrypoint_status",
            return_value={"status": "available"},
        ), mock.patch(
            "gategpt_testbench_probe.subprocess.run",
        ) as run:
            cwd = Path(tmpdir)
            eval_repo = cwd / "gateGPT"
            obj_dir = eval_repo / "obj_tb_core"
            obj_dir.mkdir(parents=True)
            (obj_dir / "vl_batch_gpu.meta.json").write_text(
                json.dumps({"storage_size": 4416}),
                encoding="utf-8",
            )
            for rel in ORDERING_AWARE_FULL_PHASE_ENTRY_SLICED_CUBINS:
                path = cwd / rel
                path.parent.mkdir(parents=True, exist_ok=True)
                path.with_suffix(".ptx").write_text("// stale slice\n", encoding="utf-8")
                path.write_bytes(b"stale cubin")
                os.utime(path.with_suffix(".ptx"), (100.0, 100.0))
                os.utime(path, (100.0, 100.0))
            source_ptx = obj_dir / "vl_batch_gpu.ptx"
            source_ptx.write_text("// newer source ptx\n", encoding="utf-8")
            os.utime(source_ptx, (200.0, 200.0))

            def fake_regenerate(*args, **kwargs):
                for rel in ORDERING_AWARE_FULL_PHASE_ENTRY_SLICED_CUBINS:
                    path = cwd / rel
                    path.with_suffix(".ptx").write_text("// fresh slice\n", encoding="utf-8")
                    path.write_bytes(b"fresh cubin")
                    os.utime(path.with_suffix(".ptx"), (300.0, 300.0))
                    os.utime(path, (300.0, 300.0))
                return {
                    "status": "entry_sliced_cubin_chain_regenerated",
                    "runtime_authority": False,
                    "speedup_claimed": False,
                    "usefulness_claimed": False,
                }

            run.side_effect = [
                subprocess.CompletedProcess(
                    args=["build"],
                    returncode=0,
                    stdout="",
                    stderr="",
                ),
                subprocess.CompletedProcess(
                    args=["module-check"],
                    returncode=0,
                    stdout="",
                    stderr="",
                ),
            ]
            with mock.patch(
                "gategpt_testbench_probe.regenerate_chain",
                side_effect=fake_regenerate,
            ) as regenerate:
                result = run_ordering_aware_full_phase_preflight(
                    cwd,
                    eval_repo,
                    jobs=1,
                    target_state_count=2,
                    regenerate_entry_sliced_cubin_chain=True,
                    entry_sliced_ptxas_timeout_seconds=5.0,
                )

        self.assertEqual(result["status"], "ordering_aware_full_phase_preflight_passed")
        regenerate.assert_called_once()
        self.assertEqual(run.call_count, 2)
        self.assertEqual(result["entry_sliced_cubin_stale_artifacts"], [])
        self.assertEqual(
            result["entry_sliced_cubin_chain_regeneration"]["status"],
            "entry_sliced_cubin_chain_regenerated",
        )

