    def test_selector_counter_smoke_classifies_stable_path_store_site_compare(
        self,
    ) -> None:
        from gategpt_testbench_probe import run_gate_gpt_gpu_selector_counter_smoke

        selector_summary = {
            "selector_abi_available": True,
            "selector_observed_slot_count": 24,
            "selector_guarded_actual_valid_candidate_count": 24,
            "selector_actual_valid_materialized_slot_count": 0,
            "runtime_selected_phi_incoming_edge_index_count": 24,
            "runtime_selected_phi_incoming_value_materialized_count": 24,
            "runtime_selected_phi_incoming_value_compare_count": 24,
            "runtime_selected_phi_incoming_value_mismatch_count": 24,
            "runtime_selected_phi_incoming_value_store_site_reached_count": 24,
            "selected_phi_incoming_value_store_site_reached_authority": (
                "selected_phi_incoming_value_store_site_reached_unproven_return_compare_proxy_no_actual_valid_authority"
            ),
            "runtime_selected_phi_incoming_value_store_site_immediate_compare_count": 24,
            "runtime_selected_phi_incoming_value_store_site_immediate_mismatch_count": 24,
            "runtime_selected_phi_incoming_value_store_site_immediate_expected_valid_count": 0,
            "runtime_selected_phi_incoming_value_store_site_immediate_expected_valid_missing_count": 24,
            "selected_phi_incoming_value_materialized_store_samples": [
                {
                    "slot": 24,
                    "incoming_edge_index": 4,
                    "materialized_value": 4232314521,
                    "actual_value": 4232314521,
                    "expected_value": 4284088574,
                }
            ],
            "selector_actual_valid_authority_review": "blocked_missing_value_semantic_authority",
        }
        with tempfile.TemporaryDirectory() as tmpdir, mock.patch(
            "gategpt_testbench_probe.run_gpu_smoke_for_testbench",
            return_value={"build_status": "passed", "launch_status": "passed"},
        ), mock.patch(
            "gategpt_testbench_probe.tb_core_structured_output_manifest",
            return_value={"status": "available"},
        ), mock.patch(
            "gategpt_testbench_probe._gpu_kernel_entrypoint_status",
            return_value={"status": "available"},
        ), mock.patch(
            "gategpt_testbench_probe.define_tb_core_many_independent_scenario_seed_matrix",
            return_value=[],
        ), mock.patch(
            "gategpt_testbench_probe.generate_tb_core_cpu_oracles_for_seed_matrix",
            return_value={"status": "passed"},
        ), mock.patch(
            "gategpt_testbench_probe.run_tb_core_ordering_aware_token_loop_abi_probe",
            return_value={
                "status": "passed",
                "runtime_summary": {
                    "diagnostic_entry_phi_predecessor_selector_abi": selector_summary
                },
            },
        ):
            opt_ir = Path(tmpdir) / "gateGPT" / "obj_tb_core" / "vl_batch_gpu_opt.ll"
            opt_ir.parent.mkdir(parents=True)
            opt_ir.write_text(
                "\n".join(
                    [
                        "%compact.cfg_clone.entry_phi.selected_value.store_site_reached.return_compare_proxy = getelementptr inbounds i64, ptr %counters, i64 751",
                        "%1 = atomicrmw volatile add ptr %compact.cfg_clone.entry_phi.selected_value.store_site_reached.return_compare_proxy, i64 1 monotonic, align 8, !vlgpu.eval_hot_path_compact_cluster_entry_phi_selected_incoming_value_store_site_reached_return_compare_proxy_runtime_counter !1",
                        '!1 = !{!"entry_phi_selected_incoming_value_store_site_reached_unproven_return_compare_proxy_no_actual_valid_authority"}',
                        "%compact.cfg_clone.entry_phi.selected_value.store_compare.stable_return_path.slot_counter = getelementptr inbounds i64, ptr %compare_counters, i64 463",
                        "%2 = atomicrmw volatile add ptr %compact.cfg_clone.entry_phi.selected_value.store_compare.stable_return_path.slot_counter, i64 1 monotonic, align 8, !vlgpu.eval_hot_path_compact_cluster_entry_phi_selected_incoming_value_store_site_compare_stable_return_path_runtime_counter !2",
                        '!2 = !{!"entry_phi_selected_incoming_value_store_site_compare_moved_to_stable_return_path_no_actual_valid_authority"}',
                        "%compact.cfg_clone.entry_phi.selected_value.store_mismatch.stable_return_path.slot_counter = getelementptr inbounds i64, ptr %compare_counters, i64 511",
                        "%3 = atomicrmw volatile add ptr %compact.cfg_clone.entry_phi.selected_value.store_mismatch.stable_return_path.slot_counter, i64 %mismatch monotonic, align 8, !vlgpu.eval_hot_path_compact_cluster_entry_phi_selected_incoming_value_store_site_mismatch_stable_return_path_runtime_counter !3",
                        '!3 = !{!"entry_phi_selected_incoming_value_store_site_mismatch_moved_to_stable_return_path_no_actual_valid_authority"}',
                    ]
                ),
                encoding="utf-8",
            )
            result = run_gate_gpt_gpu_selector_counter_smoke(
                Path(tmpdir), Path(tmpdir) / "gateGPT", target_state_count=2
            )

        self.assertEqual(
            result["next_action"],
            "debug_selected_phi_incoming_value_wrong_incoming_mapping_before_actual_valid",
        )
        self.assertTrue(
            result["selected_phi_incoming_store_site_stable_path_compare_retained"]
        )
        elision = result["selected_phi_incoming_store_site_path_elision_summary"]
        self.assertEqual(
            elision["status"],
            "store_site_compare_moved_to_stable_return_path_return_compare_proxy_retained",
        )
        self.assertTrue(
            elision["stable_return_path_store_site_compare_counter_present"]
        )
        self.assertTrue(
            elision["stable_return_path_store_site_mismatch_counter_present"]
        )
        self.assertFalse(elision["actual_valid_authority_claimed"])
        stable_mismatch = result[
            "selected_phi_incoming_store_site_stable_path_mismatch_summary"
        ]
        self.assertEqual(
            stable_mismatch["status"],
            "stable_path_store_site_mismatch_matches_materialized_selected_value",
        )
        self.assertEqual(stable_mismatch["wrong_incoming_mapping_sample_count"], 1)
        self.assertFalse(stable_mismatch["actual_valid_authority_claimed"])

