    def test_gpu_runtime_summary_parser_extracts_stage124_transition_probe(self) -> None:
        from gategpt_testbench_probe import (
            _parse_runtime_summary,
            _stage124_record318_transition_next_action,
        )

        summary = _parse_runtime_summary(
            "ordering_aware_token_loop_high_eval_callee0_nested_call_body_record318_transition_probe: "
            "requested=true diagnostic_point=post_token_loop_sync current_phase=2 "
            "low_step=0 low_start=0 low_count=6 high_count=6 cycle_count=1701 "
            "nstates=2 record=318 record_addr=3544 pair_record_span=12 "
            "pair_record_count=20412 pair_offsets_base=1000 pair_offsets_bytes=163296 "
            "progress_stage=124 transition_complete=true control_word=288240003957 "
            "boundary_kind=post_suppression_record318_transition boundary_kind_id=10 "
            "source_id=1337 result=after_only_polluted result_id=6 event_kind_id=4 "
            "before_target_direct_param_record318=0 after_target_direct_param_record318=38666621 "
            "pair_offsets_param_int_before=1000 pair_offsets_param_int_after=1000 "
            "skipped_count=1536 view_mask=19 before_after_changed=true "
            "after_polluted=true pair_offsets_base_changed=true transition_found=true "
            "write_source_authority=none scan_complete=true semantic_authority=false"
        )

        event = summary[
            "ordering_aware_token_loop_high_eval_callee0_nested_call_body_record318_transition_probe"
        ]
        self.assertEqual(event["boundary_kind"], "post_suppression_record318_transition")
        self.assertEqual(event["source_id"], 1337)
        self.assertTrue(event["transition_found"])
        self.assertEqual(event["after_target_direct_param_record318"], 38666621)
        self.assertEqual(
            _stage124_record318_transition_next_action(
                {
                    "stage124_record318_transition_probe_requested": True,
                    "stage124_record318_transition_found": True,
                }
            ),
            "validate_stage124_record318_transition_source_against_cpu_oracle_cuda700",
        )
        self.assertEqual(
            _stage124_record318_transition_next_action(
                {
                    "stage124_record318_transition_probe_requested": True,
                    "stage124_record318_transition_found": False,
                    "stage124_record318_transition_probe_event": {
                        "transition_complete": True,
                        "transition_found": False,
                    },
                }
            ),
            "advance_stage124_record318_transition_probe_range_cuda700",
        )
        self.assertEqual(
            _stage124_record318_transition_next_action(
                {
                    "stage124_record318_transition_probe_requested": True,
                    "stage124_record318_transition_found": False,
                    "stage124_record318_transition_probe_event": {
                        "transition_complete": False,
                        "transition_found": False,
                    },
                }
            ),
            "bisect_stage124_record318_transition_probe_reachability_boundary_cuda700",
        )

