    def test_gpu_build_command_can_disable_cfg_clone_diagnostics(self) -> None:
        from gategpt_testbench_probe import gpu_build_command

        command = gpu_build_command(
            Path("artifacts/external_gateGPT/obj_tb_core"),
            jobs=2,
            disable_cfg_clone_diagnostics=True,
        )

        self.assertIn("--disable-cfg-clone-diagnostics", command)
        self.assertEqual(command[-1], "--disable-cfg-clone-diagnostics")

    def test_runtime_disables_cfg_clone_shadow_allocations_with_diagnostic_abi(
        self,
    ) -> None:
        source = (REPO_ROOT / "src/hybrid/run_vl_hybrid.c").read_text(
            encoding="utf-8"
        )
        self.assertIn("ENV_DISABLE_CFG_CLONE_DIAGNOSTIC_ABI", source)
        self.assertIn(
            "if (cfg_clone_diagnostic_abi_enabled) {\n"
            "    CUDA_CHECK(cuMemAlloc(&d_single_entry_cfg_clone_liveout_counters",
            source,
        )
        self.assertIn(
            "if (ordering_aware_token_loop_abi.requested || "
            "ordering_aware_region_timing_requested) {\n"
            "    ordering_aware_token_loop_available = "
            "resolve_optional_function_across_modules",
            source,
        )

    def test_prepare_tb_core_nondiagnostic_obj_dir_rebuilds_separate_artifact(
        self,
    ) -> None:
        from gategpt_testbench_probe import prepare_tb_core_nondiagnostic_obj_dir

        with tempfile.TemporaryDirectory() as tmpdir, mock.patch(
            "gategpt_testbench_probe.subprocess.run",
            return_value=subprocess.CompletedProcess(
                args=["build"],
                returncode=0,
                stdout="",
                stderr="",
            ),
        ) as run:
            root = Path(tmpdir)
            repo = root / "gateGPT"
            source = repo / "obj_tb_core"
            source.mkdir(parents=True)
            (source / "Vtb_core_classes.mk").write_text("# fixture\n", encoding="utf-8")

            result = prepare_tb_core_nondiagnostic_obj_dir(root, repo, jobs=2)

        self.assertEqual(result["status"], "available")
        self.assertEqual(result["source_obj_dir"], "gateGPT/obj_tb_core")
        self.assertEqual(result["dest_obj_dir"], "gateGPT/obj_tb_core_nondiagnostic")
        self.assertIn("--disable-cfg-clone-diagnostics", result["build_command"])
        self.assertTrue(result["disable_cfg_clone_diagnostics"])
        self.assertEqual(
            result["runtime_disable_env"],
            "RUN_VL_HYBRID_DISABLE_CFG_CLONE_DIAGNOSTIC_ABI",
        )
        self.assertEqual(run.call_args.kwargs["cwd"], root)

