    def test_gpu_smoke_without_local_eval_fails_closed(self) -> None:
        from gategpt_testbench_probe import build_gate_gpt_testbench_manifest

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            repo = root / "external_gateGPT"
            (repo / "sim").mkdir(parents=True)
            (repo / "core").mkdir()
            for path in ("sim/tb_mathops.v", "core/udiv.v", "core/isqrt.v"):
                (repo / path).write_text("// fixture\n", encoding="utf-8")

            manifest = build_gate_gpt_testbench_manifest(repo, cwd=root, run_gpu_smoke=True)

        self.assertEqual(manifest["status"], "gategpt_gpu_smoke_blocked")
