    def test_tb_mathops_done_event_compare_detects_expected_results(self) -> None:
        from gategpt_testbench_probe import _compare_tb_mathops_events, _done_events

        rows = [
            {"step": 1, "d_done": 0, "d_quo": 0},
            {"step": 2, "d_done": 1, "d_quo": 5},
            {"step": 3, "d_done": 1, "d_quo": 5},
            {"step": 4, "d_done": 0, "d_quo": 5},
            {"step": 5, "d_done": 1, "d_quo": 9},
        ]
        events = _done_events(rows, "d_done", "d_quo")
        expected_cases = (
            {"case": "first", "expected": 5},
            {"case": "second", "expected": 9},
        )

        compared = _compare_tb_mathops_events(expected_cases, events)

        self.assertEqual([event["step"] for event in events], [2, 5])
        self.assertEqual([case["status"] for case in compared], ["passed", "passed"])

    def test_tb_mathops_pass_fail_policy_accepts_full_manifest_compare_without_stdout_claim(self) -> None:
        from gategpt_testbench_probe import (
            TB_MATHOPS_DIV_CASES,
            TB_MATHOPS_SQRT_CASES,
            _compare_tb_mathops_events,
            _tb_mathops_pass_fail_policy,
        )

        divider_events = [
            {"step": index + 1, "observed_result": int(case["expected"])}
            for index, case in enumerate(TB_MATHOPS_DIV_CASES)
        ]
        sqrt_events = [
            {"step": index + 10, "observed_result": int(case["expected"])}
            for index, case in enumerate(TB_MATHOPS_SQRT_CASES)
        ]
        full_sequence = {
            "status": "passed",
            "divider_cases": _compare_tb_mathops_events(TB_MATHOPS_DIV_CASES, divider_events),
            "sqrt_cases": _compare_tb_mathops_events(TB_MATHOPS_SQRT_CASES, sqrt_events),
            "final_fields": {"errors": 0},
        }

        policy = _tb_mathops_pass_fail_policy(full_sequence)

        self.assertEqual(policy["status"], "passed")
        self.assertTrue(policy["selected_testcase_pass_fail_policy_claimed"])
        self.assertFalse(policy["stdout_pass_fail_export_claimed"])
        self.assertFalse(policy["finish_export_claimed"])
        self.assertEqual(policy["expected_case_count"], 13)
        self.assertEqual(policy["observed_case_count"], 13)

    def test_cpu_output_manifest_records_stdout_finish_and_readmem_contract(self) -> None:
        from gategpt_testbench_probe import build_gate_gpt_cpu_output_manifest

        with tempfile.TemporaryDirectory() as tmpdir:
            repo = Path(tmpdir) / "gateGPT"
            (repo / "sim").mkdir(parents=True)
            (repo / "sim" / "tb_exp.v").write_text(
                'initial begin $readmemh("generated/test_exp_z.hex", mem); end\n',
                encoding="utf-8",
            )
            (repo / "sim" / "tb_core.v").write_text(
                'initial begin $readmemh("generated/token.hex", toks); end\n',
                encoding="utf-8",
            )
            runs = [
                {
                    "testbench": "tb_exp",
                    "status": "passed",
                    "run_stdout": "\n".join(
                        [
                            "EXP PASS: all 103 cases match",
                            "- sim/tb_exp.v:30: Verilog $finish",
                            "- Verilator: cpu 0.000 s on 1 threads",
                        ]
                    ),
                },
                {
                    "testbench": "tb_core",
                    "status": "passed",
                    "run_stdout": "\n".join(
                        [
                            "CYCLES_PER_TOKEN = 1157",
                            "greedy tokens: 1 12 1 25 1",
                            "AVG_CYCLES = 1322 over 12 tokens (last=1489)",
                            "sampled tokens: 18 15 19 16 8 15 4",
                            "CORE PASS: greedy + sampled match golden",
                            "- sim/tb_core.v:84: Verilog $finish",
                        ]
                    ),
                },
            ]

            manifest = build_gate_gpt_cpu_output_manifest(repo, runs)

        self.assertEqual(manifest["status"], "available")
        self.assertFalse(manifest["gpu_stdout_finish_export_claimed"])
        self.assertFalse(manifest["gpu_output_manifest_claimed"])
        self.assertEqual(
            manifest["readmem_init_state_contract_required_testbenches"],
            ["tb_exp", "tb_core"],
        )
        exp_entry = manifest["entries"][0]
        core_entry = manifest["entries"][1]
        self.assertEqual(exp_entry["pass_observable"]["label"], "EXP")
        self.assertEqual(exp_entry["finish_observable"]["source_line"], 30)
        self.assertEqual(exp_entry["readmem_refs"][0]["path"], "generated/test_exp_z.hex")
        self.assertIn("greedy tokens: 1 12 1 25 1", core_entry["structured_output_lines"])
        self.assertEqual(core_entry["pass_observable"]["label"], "CORE")
        self.assertEqual(core_entry["gpu_observable_export_status"], "not_exported")

