    def test_tb_norm_vector_helpers_preload_and_compare_vmem_window(self) -> None:
        from gategpt_testbench_probe import (
            _build_tb_norm_vmem_sequence_patch_lines,
            _compare_tb_norm_state_dump,
        )

        offsets = {
            "tb_norm__DOT__clk": {"offset": 0, "size": 1},
            "tb_norm__DOT__resetn": {"offset": 1, "size": 1},
            "tb_norm__DOT__start": {"offset": 2, "size": 1},
            "tb_norm__DOT__load": {"offset": 3, "size": 1},
            "tb_norm__DOT__tb_we": {"offset": 4, "size": 1},
            "tb_norm__DOT__u_vmem__DOT__mem": {"offset": 64, "size": 2048},
        }
        lines = _build_tb_norm_vmem_sequence_patch_lines(offsets, [1, -2], run_cycles=1)

        self.assertIn("64:1 65:0", lines[0])
        self.assertIn("66:254 67:255", lines[0])
        self.assertEqual(lines[-2], "0:1 1:1 2:0 3:0 4:0")

        with tempfile.TemporaryDirectory() as tmpdir:
            state = Path(tmpdir) / "state.bin"
            data = bytearray(256)
            data[64 + (64 * 2) : 64 + (64 * 2) + 2] = (123).to_bytes(2, "little")
