    def test_tb_core_replicated_state_phase_dump_compare_checks_all_states(self) -> None:
        from gategpt_testbench_probe import _compare_tb_core_replicated_state_phase_dumps

        offsets = {
            "tb_core__DOT__done": {"offset": 0, "size": 1},
            "tb_core__DOT__next_token": {"offset": 1, "size": 1},
            "tb_core__DOT__rng_out": {"offset": 4, "size": 4},
            "tb_core__DOT__cyc": {"offset": 8, "size": 4},
            "tb_core__DOT__reported": {"offset": 12, "size": 4},
            "tb_core__DOT__tot_cyc": {"offset": 16, "size": 4},
            "tb_core__DOT__tot_tok": {"offset": 20, "size": 4},
        }
        storage_size = 64

        def write_u32(blob: bytearray, state: int, offset: int, value: int) -> None:
            start = (state * storage_size) + offset
            blob[start : start + 4] = value.to_bytes(4, "little")

        with tempfile.TemporaryDirectory() as tmpdir:
            phase1 = Path(tmpdir) / "phase1.bin"
            phase2 = Path(tmpdir) / "phase2.bin"
            p1 = bytearray(storage_size * 2)
            p2 = bytearray(storage_size * 2)
            for state in range(2):
                p1[(state * storage_size) + 1] = 1
                write_u32(p1, state, 16, 1157)
                p2[(state * storage_size) + 1] = 2
                write_u32(p2, state, 8, 1489)
                write_u32(p2, state, 12, 12)
                write_u32(p2, state, 16, 15871)
                write_u32(p2, state, 20, 12)
            phase1.write_bytes(p1)
            phase2.write_bytes(p2)

            result = _compare_tb_core_replicated_state_phase_dumps(
                [phase1, phase2],
                offsets,
                [1, 2],
                nstates=2,
                storage_size=storage_size,
            )

        self.assertEqual(result["state_count"], 2)
        self.assertEqual(result["passed_count"], 2)
        self.assertEqual(result["mismatch_count"], 0)
        self.assertTrue(result["semantic_equivalence_claimed"])
        self.assertFalse(result["mixed_scenario_claimed"])

