                    "feedback_edges: requested=true mode=phase edges=5 launched=1 kernel=vl_apply_feedback_edges_gpu",
                    "feedback_increments: requested=true mode=phase increments=1 launched=1 kernel=vl_apply_feedback_increments_gpu",
                    "feedback_phase_sets: requested=true sets=8 launched=2 kernel=vl_apply_feedback_sets_gpu",
                    "feedback_combined: requested=true launched=1 kernel=vl_apply_feedback_combined_gpu",
                    "gpu_kernel_launches: logical=2 actual=3 timing_repeats=1 ms_per_actual_launch=5.0",
