        self.assertEqual(summary["gpu_kernel_actual_launch_count"], 3)
        self.assertEqual(summary["gpu_kernel_timing_repeats"], 1)
        self.assertEqual(summary["gpu_kernel_ms_per_actual_launch"], 5.0)

