    def test_tb_core_cpu_oracle_generation_fills_seed_matrix(self) -> None:
        from gategpt_testbench_probe import (
            define_tb_core_many_independent_scenario_seed_matrix,
            generate_tb_core_cpu_oracles_for_seed_matrix,
        )

        with tempfile.TemporaryDirectory() as tmpdir:
            root = Path(tmpdir)
            repo = root / "artifacts" / "eval" / "gateGPT"
            (repo / "sim").mkdir(parents=True)
            (repo / "core").mkdir(parents=True)
            (repo / "core" / "microgpt_core.v").write_text("module microgpt_core; endmodule\n", encoding="utf-8")
            seed_matrix = define_tb_core_many_independent_scenario_seed_matrix(target_state_count=4)

            def fake_run(command, **kwargs):
                if command[0] == "verilator":
                    return subprocess.CompletedProcess(args=command, returncode=0, stdout="build ok\n", stderr="")
                return subprocess.CompletedProcess(
                    args=command,
                    returncode=0,
                    stdout=(
                        "ORACLE sampled_seed2: mode=1 seed=2 inv_temp=2926 len=7 tokens=18 15 19 16 8 15 4\n"
                        "ORACLE sampled_seed3: mode=1 seed=3 inv_temp=2926 len=3 tokens=1 2 3\n"
                        "ORACLE sampled_seed4: mode=1 seed=4 inv_temp=2926 len=2 tokens=4 5\n"
                    ),
                    stderr="",
                )

            with mock.patch("gategpt_testbench_probe.subprocess.run", side_effect=fake_run):
                result = generate_tb_core_cpu_oracles_for_seed_matrix(root, repo, seed_matrix)

            generated_bench = repo / "sim" / "tb_core_seed_matrix_oracle.v"
            generated_bench_exists = generated_bench.exists()
            generated_bench_text = generated_bench.read_text(encoding="utf-8")

        self.assertEqual(result["status"], "passed")
        self.assertTrue(generated_bench_exists)
        self.assertIn("resetn = 0; start = 0;", generated_bench_text)
        self.assertIn('run_gen("greedy", 1\'d0, 32\'d0, 16\'sd0);', generated_bench_text)
        self.assertIn('run_gen("sampled_seed4", 1\'d1, 32\'d4, 16\'sd2926);', generated_bench_text)
        self.assertEqual(result["scenario_count"], 4)
        self.assertEqual(result["target_state_count"], 4)
        self.assertEqual(result["known_oracle_count"], 4)
        self.assertEqual(result["pending_oracle_count"], 0)
        self.assertEqual(result["oracle_validation_mismatch_count"], 0)
        self.assertEqual(
            result["scenario_table"][1]["oracle_status"],
            "known_from_tb_core_stdout_golden",
        )
        self.assertEqual(
            result["scenario_table"][1]["oracle_validation_status"],
            "matched_cpu_verilator_seed_matrix_oracle",
        )
        self.assertEqual(result["scenario_table"][2]["expected_with_delimiters"], [1, 2, 3, 0])
        self.assertEqual(result["scenario_table"][3]["expected_with_delimiters"], [4, 5, 0])
        self.assertFalse(result["speedup_claimed"])
        self.assertFalse(result["usefulness_claimed"])
        self.assertEqual(result["next_contract"], "run_many_independent_state_indexed_tb_core_batch_repeat_median")

