    def test_tb_core_phase_set_control_can_trim_final_low_step(self) -> None:
        from gategpt_testbench_probe import _build_tb_core_phase_set_start_control_patch_lines

        offsets = {
            "tb_core__DOT__clk": {"offset": 1},
            "tb_core__DOT__resetn": {"offset": 2},
            "tb_core__DOT__start": {"offset": 3},
        }

        untrimmed = _build_tb_core_phase_set_start_control_patch_lines(
            offsets,
            nstates=2,
            run_cycles=2,
        )
        trimmed = _build_tb_core_phase_set_start_control_patch_lines(
            offsets,
            nstates=2,
            run_cycles=2,
            trim_final_low=True,
        )

        self.assertEqual(len(untrimmed), 7)
