    def test_tb_core_many_independent_hold_start_repeat_is_prefix_only(self) -> None:
        from gategpt_testbench_probe import run_tb_core_many_independent_hold_start_repeat_probe

        scenarios = [
            {
                "state": idx,
                "name": f"s{idx}",
                "expected_with_delimiters": [idx, 0],
                "token_in": 0,
                "pos_in": 0,
                "rng_in": idx,
                "sample_mode": 1,
                "inv_temp": 2926,
            }
            for idx in range(2)
        ]

        def fake_phase_probe(*_args, **kwargs):
            self.assertTrue(kwargs["hold_start_after_phase_set"])
            self.assertFalse(kwargs["global_start_prefix_only"])
            return {
                "status": "passed",
                "prefix_sequence_claimed": True,
                "full_sequence_claimed": False,
                "comparison": {
                    "state_count": len(kwargs["scenarios"]),
                    "passed_count": len(kwargs["scenarios"]),
                    "mismatch_count": 0,
                },
                "runtime_summary": {
                    "wall_time_ms": 20.0,
                    "gpu_kernel_total_ms": 19.0,
                    "gpu_kernel_actual_launch_count": 26,
                    "gpu_kernel_logical_launch_count": 30618,
                    "feedback_phase_sets": {"launch_count": 9},
                    "feedback_combined": {"launch_count": 8},
                    "pair_cycle_fusion": {"launch_count": 0},
                    "pair_cycle_loop_fusion": {
                        "kernel_launch_count": 9,
                        "fallback_count": 0,
                    },
                },
            }

        with tempfile.TemporaryDirectory() as tmpdir, mock.patch(
            "gategpt_testbench_probe.run_tb_core_distinct_state_full_sequence_phase_set_probe",
            side_effect=fake_phase_probe,
        ):
            result = run_tb_core_many_independent_hold_start_repeat_probe(
                Path(tmpdir),
                Path(tmpdir),
                {"status": "available"},
                {"status": "available"},
                {"status": "available"},
                {"status": "available"},
                {
                    "status": "passed",
                    "scenario_table": scenarios,
                    "known_oracle_count": 2,
                    "pending_oracle_count": 0,
                },
                repeat_count=3,
                target_state_count=2,
            )

        self.assertEqual(result["status"], "passed")
        self.assertTrue(result["prefix_sequence_claimed"])
        self.assertFalse(result["full_sequence_claimed"])
        self.assertFalse(result["semantic_equivalence_claimed"])
        self.assertFalse(result["many_independent_scenario_claimed"])
        self.assertEqual(result["gpu_kernel_actual_launch_count_median"], 26)
        self.assertEqual(result["pair_cycle_fusion_launch_count_median"], 0)
        self.assertFalse(result["speedup_claimed"])
        self.assertFalse(result["usefulness_claimed"])

