    def test_tb_core_ordering_aware_token_loop_abi_probe_blocks_chunked_plan_without_continuation_abi(self) -> None:
        from gategpt_testbench_probe import run_tb_core_ordering_aware_token_loop_abi_probe

        scenarios = [
            {
                "state": idx,
                "name": f"s{idx}",
                "expected_with_delimiters": [idx, 0],
                "token_in": 0,
                "pos_in": 0,
                "rng_in": idx,
                "sample_mode": 1,
                "inv_temp": 2926,
            }
            for idx in range(2)
        ]

        with tempfile.TemporaryDirectory() as tmpdir, mock.patch(
            "gategpt_testbench_probe.run_tb_core_distinct_state_full_sequence_phase_set_probe",
        ) as run_probe:
            obj_dir = Path(tmpdir) / "obj_tb_core"
            obj_dir.mkdir()
            (obj_dir / "vl_batch_gpu.ll").write_text("", encoding="utf-8")
            result = run_tb_core_ordering_aware_token_loop_abi_probe(
                Path(tmpdir),
                Path(tmpdir),
                {"status": "available"},
                {"status": "available"},
                {"status": "available"},
                {
                    "status": "passed",
                    "scenario_table": scenarios,
                    "known_oracle_count": 2,
                    "pending_oracle_count": 0,
                    "run_wall_time_ms": 5.0,
                },
                target_state_count=2,
                ordering_aware_loop_chunk=256,
            )

        run_probe.assert_not_called()
        self.assertEqual(
            result["status"],
            "blocked_ordering_aware_lowering_plan_runtime_unsupported",
        )
        self.assertFalse(result["runtime_supported"])
        self.assertFalse(result["runtime_correctness_claimed"])
        self.assertEqual(result["ordering_aware_loop_chunk"], 256)
        self.assertFalse(result["ordering_aware_full_logical_phase_chunk"])
        self.assertTrue(result["ordering_aware_phase_control_continuation_required"])
        self.assertFalse(result["ordering_aware_phase_control_continuation_abi_available"])
        self.assertEqual(
            result["ordering_aware_lowering_plan_validation"]["status"],
            "blocked_phase_control_chunk_continuation_requires_generated_continuation_abi",
        )
        self.assertFalse(
            result["ordering_aware_lowering_plan_validation"]["runtime_supported"]
        )
        self.assertIn("generated continuation ABI", result["blocking_reason"])
        self.assertEqual(
            result["next_contract"],
            "generate_ordering_aware_phase_control_continuation_abi_or_use_full_logical_phase_chunk",
        )

